{
  "qid": "0016-L2-01",
  "sample_id": "0016",
  "gen_prompt": "创作一幅写实航天摄影风格的16:9横幅画面：神舟七号飞船正在近地轨道飞越地球昼夜交界线。采用三分之四侧视的中近景，主体从前端到尾端全部进入画幅，无遮蔽，外观与表面细节清楚可辨。主体位于中央偏右，沿左上至右下方向斜置，占画幅宽度约三分之二。画面左下方呈现蓝色地球弧面和薄薄的大气辉光，右上方为深黑太空与稀疏星点；阳光从画面右上方照来。画面中不要出现宇航员、其他航天器或说明性文字框。",
  "invocation": "L2",
  "knowledge_dim": "中国载人飞船的舱体构型、外观配色与国别识别标志",
  "fidelity_checks": [
    {
      "check": "飞船本体呈现沿同一纵轴串联的三个明确舱段，顺序为前端轨道舱、中部返回舱、尾部推进舱；前端轨道舱为圆筒类舱体。",
      "lens": "K1",
      "anchor": {
        "type": "combination",
        "constraint_refs": [
          "1",
          "3"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "缺少任一舱段、多出主要舱段、三个舱段未沿同一纵轴串联、前中后顺序错误，或前端轨道舱被画成球体、锥体、机翼式结构等非圆筒类舱体。",
        "tier_1": "三个舱段均清楚存在，沿同一纵轴依次连接，前端轨道舱、中部返回舱和尾部推进舱的位置关系正确，且轨道舱具有可辨的圆筒类外形。",
        "tier_2": "达到Pass，并以清晰连接界面、可信的舱段过渡和精确透视充分表现三舱串联关系，即使在斜向构图中也能无歧义辨认各段。"
      },
      "variants_used": "",
      "visibility_requirement": "题面要求主体全长无遮挡且细节清楚，三个舱段及连接关系均应可见；若因生成结果裁切、遮挡或过暗而无法核验，按缺失或不可辨记Fail。"
    },
    {
      "check": "位于中部的返回舱具有钟形或钝头锥形的再入舱外形。",
      "lens": "K1",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "2"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "返回舱缺失，或被画成普通圆柱、球体、细长尖锥、带翼机身等错误形态。",
        "tier_1": "中部返回舱清楚呈钟形或钝头锥形，宽钝端与收窄端关系可辨，没有被误画成圆柱舱或带翼舱体。",
        "tier_2": "达到Pass，并准确呈现钟形轮廓、钝头体量和与相邻舱段之间可信而清晰的形态过渡。"
      },
      "variants_used": "",
      "visibility_requirement": "中部轮廓至少一侧必须完整可见并足以判断外形；题面已要求无遮挡，若轮廓被裁掉、涂抹或阴影完全吞没而不可判，记Fail。"
    },
    {
      "check": "大型展开构件仅成对安装在尾部推进舱两侧，左右对称并横向展开；前端轨道舱没有同类构件。",
      "lens": "K1",
      "anchor": {
        "type": "combination",
        "constraint_refs": [
          "4",
          "5"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "尾部缺少任一侧大型展开构件、构件安装位置不在推进舱、两侧配置明显不成对，或前端轨道舱额外装有同类构件。",
        "tier_1": "尾部推进舱左右两侧各有一块大型展开构件，构成横向展开的一对；前端轨道舱未安装同类构件。",
        "tier_2": "达到Pass，并使两侧安装根部、展开方向和对称关系高度清楚，透视缩短合理且不会造成错误归属或数量歧义。"
      },
      "variants_used": "",
      "visibility_requirement": "三分之四侧视允许远侧构件产生合理透视缩短，但两块构件及其安装归属都必须可辨；若远侧完全被遮没而无法确认，最高不超过Fail。"
    },
    {
      "check": "整体类别保持为三舱式载人飞船，不出现飞机式飞行器、单节运载箭体、空间站大型组合体或无返回舱卫星平台的形态特征。",
      "lens": "K1",
      "anchor": {
        "type": "combination",
        "constraint_refs": [
          "9",
          "10",
          "11"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "出现飞机式主翼、尾翼或起落架；整体被画成单节细长运载箭体；出现大型桁架与众多舱体组成的空间站；或成为缺少返回舱的无人卫星平台。",
        "tier_1": "整体明确属于紧凑的三舱式载人飞船，没有飞机式、运载火箭式、空间站式或无人卫星平台式的错误结构。",
        "tier_2": "达到Pass，并通过清晰的主体轮廓、紧凑舱段关系和准确附件归属，使飞船类别在复杂地球背景前仍可被立即、无歧义地识别。"
      },
      "variants_used": "",
      "visibility_requirement": "主体全轮廓必须处于画幅内；若裁切导致无法排除飞机、火箭、空间站或卫星平台形态，记Fail。"
    },
    {
      "check": "前端轨道舱外表面以白色或银白色为主基调。",
      "lens": "K2",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "6"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "轨道舱主色被画成黑色、红色、蓝色、金色等明显不同色系，或白色与银白色仅占无关紧要的小面积。",
        "tier_1": "轨道舱可见表面的主体色明确属于白色或银白色，允许受阳光、地球反光和阴影影响产生合理明暗变化。",
        "tier_2": "达到Pass，并以细腻而可信的冷暖反射、明暗层次和表面分区保持白色或银白色主调，不因强光或阴影丢失色彩归属。"
      },
      "variants_used": "",
      "visibility_requirement": "轨道舱须有足够面积处于可辨曝光范围；局部阴影不作错误处理，但若整体过暗、过曝或模糊到无法判断主色，记Fail。"
    },
    {
      "check": "中部返回舱外表面以白色或银白色为主基调。",
      "lens": "K2",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "6"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "返回舱主色明显属于白色或银白色以外的色系，或其表面被错误处理成大面积鲜艳彩色。",
        "tier_1": "返回舱可见表面的主体色为白色或银白色，并保留由当前光照造成的合理受光面与背光面差异。",
        "tier_2": "达到Pass，并在钟形曲面上以精确渐变、反射和微妙色温变化表现白色或银白色主调及立体体积。"
      },
      "variants_used": "",
      "visibility_requirement": "至少应有一片连续且曝光正常的返回舱表面可供判断；若该舱被遮挡或完全陷入无细节黑影，记Fail。"
    },
    {
      "check": "尾部推进舱外表面以白色或银白色为主基调。",
      "lens": "K2",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "6"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "推进舱主体表面被画成明显不同的主色，或以大面积黑色、鲜艳色彩覆盖而不再呈白色或银白色基调。",
        "tier_1": "推进舱主体表面清楚呈白色或银白色，附件阴影、环境色和局部深色细节不改变其主色归属。",
        "tier_2": "达到Pass，并在圆柱曲面及附件连接区域保持连贯、细致的白色或银白色层次，表面转折与受光关系清晰可信。"
      },
      "variants_used": "",
      "visibility_requirement": "推进舱的连续主体表面必须清楚可见；大型展开构件不代替对推进舱本身主色的判断，不可判时记Fail。"
    },
    {
      "check": "细节清晰的飞船外表面至少出现一种可辨认的中国识别标志。",
      "lens": "K3",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "7"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "飞船表面完全没有中国识别标志，或仅有无法辨认的色块、乱码和无明确含义的伪标记。",
        "tier_1": "至少有一种中国识别标志可清楚辨认，例如中国国旗、准确的“中国航天”或“神舟”字样，或可识别的中国载人航天工程标志。",
        "tier_2": "达到Pass，并呈现一个以上清晰、位置归属明确且尺寸适当的中国识别标志，近看仍具有完整边界或准确字形。"
      },
      "variants_used": "",
      "visibility_requirement": "题面明确要求表面细节清楚，至少一种标志必须达到可识别尺度；若所有候选标志都过小、模糊、背对镜头或被高光遮没，记Fail。"
    },
    {
      "check": "飞船本体不出现NASA等外国航天机构标志或任何外国国旗。",
      "lens": "K3",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "8"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "逐处检查飞船表面时发现NASA、ESA、Roscosmos等外国机构标志、外国国旗，或其他明确的外国航天识别文字与徽标。",
        "tier_1": "飞船表面没有任何可辨认的外国机构标志或外国国旗，出现的国别识别内容仅属于中国。",
        "tier_2": "达到Pass，并且所有可见标记均边界清楚、归属一致，在高细节表面中也没有混入疑似外国徽标或错误国旗元素。"
      },
      "variants_used": "",
      "visibility_requirement": "核验范围为飞船本体所有可见表面；若某处只是不可辨的微小机械细节，不凭猜测判为外国标志，但清楚可读的外国标志一经出现即记Fail。"
    },
    {
      "check": "所采用的中国识别标志在字形、旗面构成或徽标造型上准确，不以错字、乱码、编造字符或错误旗帜代替。",
      "lens": "K3",
      "anchor": {
        "type": "combination",
        "constraint_refs": [
          "7",
          "8"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "可见文字逐字抄录后不是准确的“中国航天”或“神舟”，含错字、乱码或编造字符；中国国旗的星形组合明显错误；或徽标造型无法对应中国载人航天工程标志并疑似其他机构标志。",
        "tier_1": "至少一种所选中国标志准确：文字可逐字正确辨认，或中国国旗的基本构成正确，或中国载人航天工程标志具有正确且可识别的造型。",
        "tier_2": "达到Pass，并且全部可见标志均准确、锐利、比例协调；文字笔画完整，旗面或徽标的关键组成关系清楚，经放大检查仍无伪字和结构错置。"
      },
      "variants_used": "",
      "visibility_requirement": "至少一种标志必须足够大且清晰以核验准确性；若仅出现不可逐字或不可辨形的模糊标记，则不能按正确处理，记Fail。"
    }
  ],
